output_text:
[
  {
    "id": "no_cart_in_pedestrian_shelf_canyon",
    "text": "Carts are forbidden in single-file aisles flanked by shelves on both sides.",
    "abstraction": {
      "state_properties": {
        "opposingShelves": {
          "and": [
            "shelfE",
            "shelfW"
          ]
        },
        "pedestrianOnlyAisle": {
          "and": [
            "opposingShelves",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "pedestrianOnlyAisle",
          "hasCart"
        ]
      }
    }
  },
  {
    "id": "no_enter_pedestrian_aisle_with_cart",
    "text": "An agent must not push a cart into a pedestrian-only single-file shelf aisle.",
    "abstraction": {
      "state_properties": {
        "pedestrianOnlyAisle": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {
        "enterPedestrianOnlyAisleWithCart": {
          "pre": {
            "and": [
              "hasCart",
              "MOVE"
            ]
          },
          "post": "pedestrianOnlyAisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "enterPedestrianOnlyAisleWithCart"
    }
  },
  {
    "id": "park_cart_only_at_aisle_mouth",
    "text": "If a cart is set down, it may only be parked at the mouth of a walk-in shelf aisle.",
    "abstraction": {
      "state_properties": {
        "cartHandoffZone": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "improperCartDrop": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT",
              {
                "not": "cartHandoffZone"
              }
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "improperCartDrop"
    }
  },
  {
    "id": "recover_parked_cart",
    "text": "After parking a cart at a shelf-aisle handoff point, the agent is obliged to pick it back up before leaving.",
    "abstraction": {
      "state_properties": {
        "cartHandoffZone": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "cartParkedAtHandoff": {
          "pre": {
            "and": [
              "cartHandoffZone",
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "cartRecoveredAtHandoff": {
          "pre": {
            "and": [
              "cartHandoffZone",
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "cartParkedAtHandoff",
      "discharge": "cartRecoveredAtHandoff"
    }
  },
  {
    "id": "no_roaming_without_cart_except_walk_in_aisles",
    "text": "Movement without a cart is allowed only at the cart bay, at a cart handoff point, or inside a pedestrian-only shelf aisle.",
    "abstraction": {
      "state_properties": {
        "cartBay": {
          "or": [
            "at(0,7)",
            "at(1,7)"
          ]
        },
        "cartHandoffZone": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "pedestrianOnlyAisle": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        },
        "allowedOnFootArea": {
          "or": [
            "cartBay",
            "cartHandoffZone",
            "pedestrianOnlyAisle"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "MOVE",
          {
            "not": "hasCart"
          },
          {
            "not": "allowedOnFootArea"
          }
        ]
      }
    }
  },
  {
    "id": "cart_required_for_open_shelf_service",
    "text": "Shelf interactions in open cart-accessible aisles require having the cart; only walk-in single-file shelf aisles may be shopped without it.",
    "abstraction": {
      "state_properties": {
        "pedestrianOnlyAisle": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        },
        "openShelfServiceSpot": {
          "and": [
            "adjShelf",
            {
              "not": "pedestrianOnlyAisle"
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "openShelfServiceSpot",
          "INTERACT",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  },
  {
    "id": "return_to_cart_after_on_foot_pickup",
    "text": "After taking an item on foot inside a pedestrian-only shelf aisle, the agent must return to the handoff point and recover the cart.",
    "abstraction": {
      "state_properties": {
        "cartHandoffZone": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "pedestrianOnlyAisle": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {
        "onFootShelfPickup": {
          "pre": {
            "and": [
              "pedestrianOnlyAisle",
              "INTERACT",
              {
                "not": "hasCart"
              }
            ]
          },
          "post": null
        },
        "cartRecoveredAtHandoff": {
          "pre": {
            "and": [
              "cartHandoffZone",
              "INTERACT",
              {
                "not": "hasCart"
              }
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "onFootShelfPickup",
      "discharge": "cartRecoveredAtHandoff"
    }
  },
  {
    "id": "exit_with_acquired_cart",
    "text": "Once an agent has taken a cart, the cart must be brought to the exit rather than abandoned in the store.",
    "abstraction": {
      "state_properties": {},
      "events": {
        "cartAcquired": {
          "pre": {
            "and": [
              "INTERACT",
              {
                "not": "hasCart"
              }
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "cartAcquired",
      "discharge": {
        "and": [
          "EXIT",
          "hasCart"
        ]
      }
    }
  }
]
